// Adds up WooCommerce orders (wc/v3/orders: processing, completed and refunded) into the report contract, in the Settings currency.
// Orders in another currency use the multi-currency plugin's base-currency meta; refunds use the order's exchange rate.
// gross = order totals after discounts; net = gross minus tax, shipping and refunds on these orders.
const base=$('Settings').first().json.currency;
if($input.all().some(i=>i.json&&Object.keys(i.json).length&&i.json.id===undefined&&!i.json.error))throw Error('No order data: the WooCommerce request node is switched off, or returned something that is not orders. Connect your store and switch it on.');
const orders=$input.all().map(i=>i.json).filter(o=>o&&o.id!==undefined);
if(orders.length&&orders[0].total===undefined)throw Error('Orders came back without totals; check the _fields parameter');
const num=v=>Number(v)||0;
const rows=orders.map(o=>{
  const refunded=(o.refunds||[]).reduce((s,r)=>s+Math.abs(num(r.total)),0);
  const items=(o.line_items||[]).reduce((s,l)=>s+num(l.quantity),0);
  if(o.currency===base)return {total:num(o.total),tax:num(o.total_tax),shipping:num(o.shipping_total),discount:num(o.discount_total),refunds:refunded,items};
  const m=Object.fromEntries((o.meta_data||[]).map(x=>[x.key,x.value]));
  if(m._order_total_base_currency===undefined||m._base_currency_exchange_rate===undefined)throw Error('Order '+o.id+' is in '+o.currency+' with no '+base+' amount stored; cannot convert it');
  const rate=num(m._base_currency_exchange_rate);
  return {total:num(m._order_total_base_currency),tax:num(m._order_tax_base_currency),shipping:num(m._order_shipping_base_currency),discount:num(m._cart_discount_base_currency),refunds:refunded*rate,items};
});
const sum=k=>rows.reduce((s,r)=>s+r[k],0);
const totals={gross:sum('total'),taxes:sum('tax'),refunds:sum('refunds'),discounts:sum('discount'),orders:rows.length,items:sum('items')};
totals.net=totals.gross-totals.taxes-sum('shipping')-totals.refunds;
return [{json:{totals}}];

