const num=v=>Number(v)||0;
const orders=raw.filter(o=>o&&o.id!==undefined);
const conv=o=>{
  const refunded=(o.refunds||[]).reduce((s,r)=>s+Math.abs(num(r.total)),0);
  if(o.currency===base)return {total:num(o.total),tax:num(o.total_tax),shipping:num(o.shipping_total),refunds:refunded};
  const m=Object.fromEntries((o.meta_data||[]).map(x=>[x.key,x.value]));
  if(m._order_total_base_currency===undefined||m._base_currency_exchange_rate===undefined)throw Error('Order '+o.id+' is in '+o.currency+' with no '+base+' amount stored');
  const rate=num(m._base_currency_exchange_rate);
  return {total:num(m._order_total_base_currency),tax:num(m._order_tax_base_currency),shipping:num(m._order_shipping_base_currency),refunds:refunded*rate};
};
const rows=orders.map(o=>({day:String(o.date_created).slice(0,10),...conv(o)}));
const windows={};
for(const [k,w] of Object.entries(p.windows)){
