  windows[k]={...w,orders:r.length,gross:Math.round(r.reduce((s,x)=>s+x.total,0)),net:Math.round(r.reduce((s,x)=>s+x.total-x.tax-x.shipping-x.refunds,0))};
}
const pct=(a,b)=>b?Math.round((a-b)/b*1000)/10:null;
